"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Search, Filter, Trash2, CheckCircle, Reply, 
  MessageSquare, Star, AlertCircle, ChevronLeft, ChevronRight, MoreHorizontal,
  Download, CheckSquare, RefreshCw
} from "lucide-react";
// 1. IMPORT TOUR GUIDE
import TourGuide from "@/components/TourGuide";

// DATA DUMMY
const initialMessages = [
  { 
    id: 1, sender: "Rian (XI RPL 1)", category: "Sarana", tagColor: "orange",
    subject: "AC di Lab Komputer Panas", preview: "Assalamualaikum kak, mau lapor AC di Lab 2 mati satu, jadi panas banget pas praktek...", 
    date: "10:45 AM", status: "unread", isStarred: true 
  },
  { 
    id: 2, sender: "Siska (X TKJ 2)", category: "Event", tagColor: "purple",
    subject: "Request Guest Star Pensi", preview: "Kak, tahun ini undang Tulus dong buat pensi sekolah! Pasti tiketnya laku keras...", 
    date: "Kemarin", status: "read", isStarred: false 
  },
  { 
    id: 3, sender: "Anonim", category: "Kurikulum", tagColor: "blue",
    subject: "Jadwal Pelajaran Bentrok", preview: "Min, jadwal olahraga kelas kami bentrok sama jam istirahat, mohon ditinjau...", 
    date: "2 Jan", status: "done", isStarred: false 
  },
  { 
    id: 4, sender: "Budi (XII OTKP)", category: "Umum", tagColor: "slate",
    subject: "Parkiran Motor Sempit", preview: "Tolong dong parkiran dirapikan lagi, motor sering baret karena desak-desakan...", 
    date: "1 Jan", status: "read", isStarred: false 
  },
];

// 2. DEFINISI LANGKAH TUR
const inboxTourSteps = [
    {
        target: '.tour-inbox-header',
        content: 'Halaman Inbox Aspirasi: Tempat menampung kritik, saran, dan laporan dari seluruh siswa.',
        disableBeacon: true,
    },
    {
        target: '.tour-folder-sidebar',
        content: 'Gunakan Sidebar ini untuk menyaring pesan: Kotak Masuk (Semua), Belum Dibaca, atau Arsip Selesai.',
        placement: 'right' as const,
    },
    {
        target: '.tour-search-bar',
        content: 'Cari pesan berdasarkan nama pengirim atau isi pesan di sini.',
    },
    {
        target: '.tour-action-menu',
        content: 'Klik menu ini untuk opsi massal: Tandai Semua Dibaca atau Export Laporan ke Excel.',
    },
    {
        target: '.tour-message-item',
        content: 'Klik pesan untuk membaca detailnya. Arahkan kursor (hover) ke pesan untuk melihat tombol aksi cepat (Balas/Hapus).',
    },
];

export default function InboxPage() {
  const [messages, setMessages] = useState(initialMessages);
  const [selectedTab, setSelectedTab] = useState("all"); 
  const [searchQuery, setSearchQuery] = useState("");
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isClient, setIsClient] = useState(false); // Fix Hydration

  useEffect(() => { setIsClient(true); }, []);

  const filteredMessages = messages.filter((msg) => {
    const matchesTab = 
      selectedTab === "all" ? msg.status !== "done" : 
      selectedTab === "done" ? msg.status === "done" :
      selectedTab === "unread" ? msg.status === "unread" : true;
    
    const matchesSearch = 
      msg.sender.toLowerCase().includes(searchQuery.toLowerCase()) || 
      msg.subject.toLowerCase().includes(searchQuery.toLowerCase());

    return matchesTab && matchesSearch;
  });

  const markAllRead = () => {
    setMessages(messages.map(m => m.status === 'unread' ? { ...m, status: 'read' } : m));
    setIsMenuOpen(false);
    alert("Semua pesan ditandai sudah dibaca! ✅");
  };

  const exportData = () => {
    setIsMenuOpen(false);
    alert("Mengunduh laporan aspirasi dalam format .CSV... 📥");
  };

  const handleMarkDone = (id: number) => {
    setMessages(messages.map(m => m.id === id ? { ...m, status: "done" } : m));
  };

  const handleDelete = (id: number) => {
    if(confirm("Hapus pesan ini?")) {
      setMessages(messages.filter(m => m.id !== id));
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      
      {/* HEADER SIMPEL */}
      <div className="tour-inbox-header"> {/* Target Tur 1 */}
          <div className="flex items-center gap-3">
             <h1 className="text-3xl font-bold font-black text-slate-900 dark:text-white tracking-tight flex items-center gap-3">
               Inbox Aspirasi <span className="text-2xl p-2 bg-blue-100 dark:bg-blue-900/30 rounded-full">📩</span>
             </h1>
             {/* 3. PASANG TUR GUIDE DI SINI */}
             {isClient && <TourGuide steps={inboxTourSteps} />}
          </div>
          
          <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1 ml-1">
            Kelola pesan masuk dari seluruh siswa.
          </p>
      </div>

      {/* MAIN CONTAINER */}
      <div className="flex-1 bg-white/80 dark:bg-[#0f172a]/60 backdrop-blur-xl border border-white/50 dark:border-white/10 rounded-[2rem] overflow-hidden shadow-sm flex flex-col md:flex-row min-h-[600px]">
        
        {/* === LEFT: Sidebar Filter === */}
        {/* Target Tur 2: Sidebar */}
        <div className="tour-folder-sidebar w-full md:w-72 border-b md:border-b-0 md:border-r border-slate-200 dark:border-white/5 p-6 bg-slate-100 dark:bg-white/5 flex flex-col gap-6">
           
           <button className="w-full py-3.5 bg-blue-600 hover:bg-blue-700 active:scale-95 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-500/30 flex items-center justify-center gap-2 transition-all">
              <Filter size={18} /> Filter Lanjutan
           </button>

           <div className="space-y-2">
              <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest px-3 mb-1">Folder</p>
              {[
                { id: "all", label: "Kotak Masuk", icon: MessageSquare, count: messages.filter(m => m.status !== "done").length },
                { id: "unread", label: "Belum Dibaca", icon: AlertCircle, count: messages.filter(m => m.status === "unread").length },
                { id: "done", label: "Arsip Selesai", icon: CheckCircle, count: messages.filter(m => m.status === "done").length },
              ].map((tab) => (
                <button 
                  key={tab.id}
                  onClick={() => setSelectedTab(tab.id)}
                  className={`relative w-full flex items-center justify-between px-4 py-3 rounded-xl text-sm font-bold transition-all border group
                    ${selectedTab === tab.id 
                      ? "bg-white dark:bg-white/10 text-blue-600 dark:text-white border-blue-100 dark:border-transparent shadow-sm" 
                      : "bg-transparent border-transparent text-slate-600 dark:text-slate-400 hover:bg-white/50 dark:hover:bg-white/5 hover:text-slate-900 dark:hover:text-white"
                    }
                  `}
                >
                   {selectedTab === tab.id && (
                     <motion.div layoutId="activeTabIndicator" className="absolute left-0 top-3 bottom-3 w-1 bg-blue-600 rounded-r-full" />
                   )}

                   <div className="flex items-center gap-3">
                      <tab.icon size={18} className={selectedTab === tab.id ? "text-blue-500 dark:text-blue-400" : "opacity-70 group-hover:opacity-100"} />
                      {tab.label}
                   </div>
                   {tab.count > 0 && (
                     <span className={`text-[10px] font-extrabold px-2.5 py-0.5 rounded-full 
                       ${selectedTab === tab.id ? "bg-blue-100 text-blue-600 dark:bg-blue-600 dark:text-white" : "bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-300"}
                     `}>
                       {tab.count}
                     </span>
                   )}
                </button>
              ))}
           </div>
        </div>

        {/* === RIGHT: Content Area === */}
        <div className="flex-1 flex flex-col bg-white dark:bg-transparent">
           
           {/* TOOLBAR & SEARCH */}
           <div className="p-4 border-b border-slate-100 dark:border-white/5 flex items-center justify-between gap-4 relative z-20">
              
              {/* Target Tur 3: Search Bar */}
              <div className="relative flex-1 max-w-md tour-search-bar">
                 <input 
                   type="text" 
                   placeholder="Cari pesan..." 
                   value={searchQuery}
                   onChange={(e) => setSearchQuery(e.target.value)}
                   className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 focus:ring-2 focus:ring-blue-500/20 outline-none transition-all text-sm font-medium text-slate-700 dark:text-white"
                 />
                 <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
              </div>
              
              {/* Target Tur 4: Action Menu */}
              <div className="relative tour-action-menu">
                 <button 
                    onClick={() => setIsMenuOpen(!isMenuOpen)}
                    className={`p-2 rounded-lg transition-colors ${isMenuOpen ? 'bg-blue-50 text-blue-600 dark:bg-white/10 dark:text-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100 dark:hover:bg-white/5'}`}
                 >
                    <MoreHorizontal size={20}/>
                 </button>

                 <AnimatePresence>
                   {isMenuOpen && (
                     <motion.div 
                       initial={{ opacity: 0, y: 10, scale: 0.95 }}
                       animate={{ opacity: 1, y: 0, scale: 1 }}
                       exit={{ opacity: 0, y: 10, scale: 0.95 }}
                       className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 rounded-xl shadow-xl z-50 overflow-hidden"
                     >
                        <button onClick={markAllRead} className="w-full text-left px-4 py-3 text-xs font-bold text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-white/5 flex items-center gap-2">
                           <CheckSquare size={14} className="text-blue-500" /> Tandai Semua Dibaca
                        </button>
                        <button onClick={() => window.location.reload()} className="w-full text-left px-4 py-3 text-xs font-bold text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-white/5 flex items-center gap-2">
                           <RefreshCw size={14} className="text-green-500" /> Muat Ulang Data
                        </button>
                        <div className="h-[1px] bg-slate-100 dark:bg-white/5 my-1" />
                        <button onClick={exportData} className="w-full text-left px-4 py-3 text-xs font-bold text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-white/5 flex items-center gap-2">
                           <Download size={14} className="text-purple-500" /> Export Laporan
                        </button>
                     </motion.div>
                   )}
                 </AnimatePresence>
              </div>
           </div>

           {/* LIST PESAN */}
           <div className="flex-1 p-4 md:p-6 overflow-y-auto bg-slate-50/30 dark:bg-transparent" onClick={() => setIsMenuOpen(false)}>
             <div className="space-y-3">
               <AnimatePresence>
                 {filteredMessages.length > 0 ? (
                   filteredMessages.map((msg, index) => (
                     <motion.div 
                       key={msg.id}
                       initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95 }}
                       layout
                       // Target Tur 5: Hanya pesan pertama yang jadi target sorotan
                       className={`group relative p-5 rounded-2xl border transition-all cursor-pointer hover:shadow-lg hover:-translate-y-0.5 ${index === 0 ? 'tour-message-item' : ''}
                         ${msg.status === "unread" 
                           ? "bg-white dark:bg-white/10 border-blue-200 dark:border-blue-500/30 shadow-sm shadow-blue-500/5 ring-1 ring-blue-50 dark:ring-0" 
                           : "bg-white dark:bg-white/5 border-slate-100 dark:border-white/5 opacity-90 hover:opacity-100"
                         }
                       `}
                     >
                        <div className="flex justify-between items-start mb-3">
                           <div className="flex items-center gap-3">
                              <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold text-white shadow-sm
                                 ${msg.tagColor === "orange" ? "bg-gradient-to-br from-orange-400 to-red-500" : 
                                   msg.tagColor === "purple" ? "bg-gradient-to-br from-purple-400 to-pink-500" : 
                                   msg.tagColor === "blue" ? "bg-gradient-to-br from-blue-400 to-cyan-500" : "bg-slate-400"}
                              `}>
                                 {msg.sender.charAt(0)}
                              </div>
                              <div>
                                 <div className="flex items-center gap-2">
                                   <h4 className={`text-sm ${msg.status === "unread" ? "font-black text-slate-900 dark:text-white" : "font-bold text-slate-700 dark:text-slate-300"}`}>
                                     {msg.sender}
                                   </h4>
                                   <span className={`text-[10px] px-2 py-0.5 rounded-md font-bold uppercase tracking-wider bg-${msg.tagColor}-100 text-${msg.tagColor}-700 dark:bg-${msg.tagColor}-500/20 dark:text-${msg.tagColor}-300`}>
                                     {msg.category}
                                   </span>
                                 </div>
                                 <span className="text-xs text-slate-500 dark:text-slate-400">
                                   {msg.status === "unread" ? "Mengirim pesan baru" : "Pesan telah dibaca"}
                                 </span>
                              </div>
                           </div>
                           <div className="text-right">
                              <span className={`text-xs font-bold ${msg.status === "unread" ? "text-blue-600 dark:text-blue-400" : "text-slate-400"}`}>
                                {msg.date}
                              </span>
                           </div>
                        </div>

                        <div className="pl-13 md:pl-13">
                          <div className="flex items-center justify-between">
                              <h3 className={`text-sm mb-1 ${msg.status === "unread" ? "font-bold text-slate-900 dark:text-white" : "font-medium text-slate-600 dark:text-slate-400"}`}>
                                  {msg.subject}
                              </h3>
                              {msg.isStarred && <Star size={14} className="text-yellow-400 fill-current" />}
                          </div>
                          <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 leading-relaxed">
                              {msg.preview}
                          </p>
                        </div>

                        {/* Action Buttons */}
                        <div className="absolute right-4 bottom-4 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                           <button title="Balas" className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 hover:border-blue-500 text-slate-500 hover:text-blue-500 rounded-lg shadow-sm transition-colors"><Reply size={14} /></button>
                           {msg.status !== "done" && (
                             <button onClick={() => handleMarkDone(msg.id)} title="Selesai" className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 hover:border-green-500 text-slate-500 hover:text-green-500 rounded-lg shadow-sm transition-colors"><CheckCircle size={14} /></button>
                           )}
                           <button onClick={() => handleDelete(msg.id)} title="Hapus" className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 hover:border-red-500 text-slate-500 hover:text-red-500 rounded-lg shadow-sm transition-colors"><Trash2 size={14} /></button>
                        </div>
                     </motion.div>
                   ))
                 ) : (
                   <div className="flex flex-col items-center justify-center h-full py-20 text-center text-slate-400">
                      <div className="w-16 h-16 bg-slate-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-4"><Filter size={24} className="opacity-30" /></div>
                      <p className="text-sm font-bold text-slate-600 dark:text-slate-300">Tidak ada pesan</p>
                   </div>
                 )}
               </AnimatePresence>
             </div>
           </div>

           {/* PAGINATION FOOTER */}
           <div className="p-4 border-t border-slate-100 dark:border-white/5 bg-white dark:bg-transparent flex items-center justify-between text-xs text-slate-500 dark:text-slate-400">
              <span>Menampilkan <strong>1-{filteredMessages.length}</strong> dari <strong>{filteredMessages.length}</strong> pesan</span>
              <div className="flex gap-2">
                 <button disabled className="p-1.5 rounded-lg border border-slate-200 dark:border-white/10 opacity-50 cursor-not-allowed"><ChevronLeft size={16}/></button>
                 <button disabled className="p-1.5 rounded-lg border border-slate-200 dark:border-white/10 opacity-50 cursor-not-allowed"><ChevronRight size={16}/></button>
              </div>
           </div>

        </div>

      </div>
    </div>
  );
}